// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CopyIcon } from 'lucide-react'
import type { ReactNode } from 'react'

import { Bar, Btn, DemoStage, PanelChrome, Toggle, type Build } from '@/app/demos/stage'

import { CAPTIONS, LOREM_PARAGRAPHS, LOREM_WORDS, RANDOM_SENTENCES } from './script'

const H = 176
const UNITS = ['Paragraphs', 'Sentences', 'Words'] as const

function Filler() {
  return (
    <div className="space-y-2 px-3 py-3" style={{ height: H }}>
      {[92, 80, 96, 70, 88, 64, 90, 76].map((width, index) => (
        <Bar key={index} w={`${width}%`} className="h-2 bg-white/15" />
      ))}
    </div>
  )
}

function Result({ children }: { children: ReactNode }) {
  return (
    <div
      className="overflow-hidden px-3 py-3 text-[10.5px] leading-[16px] text-ink-soft"
      style={{ height: H }}
    >
      {children}
    </div>
  )
}

const build: Build = ({ tl, q, qa, step, final, move, click, wait, cursorOut }) => {
  const spin = (slot: number) => {
    tl.to(q('reel'), { y: -slot * H, duration: 1.1, ease: 'power4.out' })
    tl.fromTo(
      q('reel'),
      { filter: 'blur(4px)' },
      { filter: 'blur(0px)', duration: 1, ease: 'power3.in' },
      '<',
    )
  }
  const pick = (unit: number) => {
    move(`unit-${unit}`)
    click(`unit-${unit}`)
    tl.to(
      qa('unit'),
      { backgroundColor: 'rgba(255,255,255,0)', color: '#8b8b9a', duration: 0.15 },
      '<',
    )
    tl.to(
      q(`unit-${unit}`),
      { backgroundColor: 'rgba(129,140,248,0.22)', color: '#f4f4f6', duration: 0.15 },
      '<',
    )
  }

  step(0)
  pick(0)
  move('generate')
  click('generate')
  spin(1)

  step(1, '+=0.4')
  pick(2)
  move('generate')
  click('generate')
  spin(3)

  step(2, '+=0.4')
  move('random')
  click('random')
  tl.to(q('random-fill'), { opacity: 1, duration: 0.2 }, '<')
  tl.to(q('random-knob'), { x: 12, duration: 0.25 }, '<')
  pick(1)
  move('generate')
  click('generate')
  spin(5)

  step(3, '+=0.4')
  move('copy')
  click('copy')
  tl.fromTo(q('copied'), { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.3 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Dummy Data spinning up lorem paragraphs, words and random sentences"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2.5">
          <div className="flex items-center gap-2">
            <div className="flex rounded-lg border border-line bg-canvas/60 p-0.5">
              {UNITS.map((unit, index) => (
                <span
                  key={unit}
                  data-d={`unit unit-${index}`}
                  className="rounded-md px-2.5 py-1 text-[10.5px] text-muted"
                >
                  {unit}
                </span>
              ))}
            </div>
            <span className="rounded-lg border border-line bg-canvas/60 px-2 py-1 font-mono text-[10.5px]">
              × 3
            </span>
            <span className="ml-auto flex items-center gap-1.5 text-[10px] text-muted">
              Random <Toggle d="random" />
            </span>
          </div>
          <div
            className="relative min-h-0 flex-1 overflow-hidden rounded-xl border border-line bg-canvas/80"
            style={{ maxHeight: H }}
          >
            <div data-d="reel">
              <Filler />
              <Result>
                {LOREM_PARAGRAPHS.map((paragraph) => (
                  <p key={paragraph} className="mb-2">
                    {paragraph}
                  </p>
                ))}
              </Result>
              <Filler />
              <Result>
                <p className="font-mono">{LOREM_WORDS}</p>
              </Result>
              <Filler />
              <Result>
                {RANDOM_SENTENCES.map((sentence) => (
                  <p key={sentence} className="mb-1.5">
                    {sentence}
                  </p>
                ))}
              </Result>
            </div>
            <span className="pointer-events-none absolute inset-x-0 top-0 h-6 bg-gradient-to-b from-canvas to-transparent" />
            <span className="pointer-events-none absolute inset-x-0 bottom-0 h-6 bg-gradient-to-t from-canvas to-transparent" />
          </div>
          <div className="flex items-center gap-2">
            <Btn d="generate" primary>
              Generate
            </Btn>
            <Btn d="copy">
              <CopyIcon className="size-3" /> Copy
            </Btn>
            <span data-d="copied" className="text-[10.5px] text-emerald opacity-0">
              Copied
            </span>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
